let temperatureArray = [];
exports.buildTemperatureData = function(){
	console.log( "build lesson page");
	
	fs.readFile("./temperature.json", function(err, data) {
            if (err) {
                console.log("DB Not Found.");
            }
            else {

				//console.log("temperature : " + data);
				var temperatureJson = JSON.parse(data);
				
				//console.log("temperature Json : " + temperatureJson)
				
				
				temperatureJson.forEach(function(item) {
					console.log(item.date + " is " + item.temperature + " degree");
					//var dataPoint = {x:item.date, y:item.temperature }
					temperatureArray.push({date:item.date, temperature:parseInt(item.temperature, 10), furnaceHour:parseFloat(item.furnaceHour)}) ;					
				});
				//console.log("temperature array : " + temperatureArray);

				//loadLessonTemplatePage();
            }
        });
}

