exports.getLessonPage = function( yearTag ){
    //console.log("get blog page: " + yearTag );

    switch( yearTag ){
        case page2016B:
            return blogPage2016;
        case page2017A:
            return blogPage2017A;
        case page2017B:
            return blogPage2017B;
        case page2018A:
            return blogPage2018A;
        case page2018B:
            return blogPage2018B;
        case page2019A:
            return blogPage2019A;
        case page2019B:
            return blogPage2019B;
        case page2019_MARCH:
            return blogPage2019March;
        case page2019_APRIL:
            return blogPage2019April;
        case page2019_MAY:
            return blogPage2019May;
        case page2019_JUNE:
            return blogPage2019June;
        case page2019_JULY:
            return blogPage2019July;
        case page2019_AUG:
            return blogPage2019Aug;
        case page2019_SEP:
            return blogPage2019Sep;
        case page2019_OCT:
            return blogPage2019Oct;
        case page2019_NOV:
            return blogPage2019Nov;
        case blogBar:
            return blogBarPage;
        default:
            console.log("!!!!!! unknown year for blog")
    }

    return blogPage2019July;
}

