function loadLessonTemplateRow(){
    console.log( "enter loadLessonTemplateRow");

    if( 0 < blogRowTemplate.length ){
        console.log("lesson template Row had been loaded.")
        buildLessonPage();
    }
    else {

        fs.readFile("./server_html/blogRowTemplate.html", function (err, data) {
            if (err) {
                console.log("blog template Not Found.");
            }
            else {
                console.log("blog template is loaded.");
                blogRowTemplate = data.toString();
                buildLessonPage();
            }
        });
    }
}

//For more UI and data process, refer storyPage.js which is the predecessor of this file.
function buildLessonPage(){
    console.log("enter buildLessonPage()")

    if( 0 < lessonPage.length ){
        console.log("lesson page had been created.")
        return;
    }

    const lessonsData = myHelper.getLessons();
    if( null == lessonsData ){
        console.log("Can't find lessons from database")
        return "";
    }

    if( Object.keys(lessonsData).length == 0 ){
        console.log( "failed to load lessons.");
        return "";
    }

    const count = lessonsData.length;
    console.log( "lessons data size : " + count);

    var resultPage = "";
    var oneResult = "";
    var finalPage2019A = "";
    var finalPage2019B = "";
    var finalPage2019March = "";
    var finalPage2019April = "";
    var finalPage2019May = "";
    var finalPage2019June = "";
    var finalPage2019July = "";
    var finalPage2019Augest = "";
    var finalPage2019September = "";
    var finalPage2019October = "";
    var finalPage2019November = "";

    var finalPage2018A = "";
    var finalPage2018B = "";
    var finalPage2017A = "";
    var finalPage2017B = "";
    var finalPage2016 = "";

    const story_body_place_holder = "body-place-holder";
    const story_title_place_holder = "title-place-holder";
    const story_section_place_holder = "blog-items-place-holder";
    const blog_section_title_holder = "blog-section-title-holder";

    for( var i = 0; i < count; ++i ){
        //console.log( "1 : " + lessonsData[i][1] ); //year
        //console.log( "2 : " + lessonsData[i][2] ); //month
        //console.log( "3 : " + lessonsData[i][3] ); //day
        //console.log( "4 : " + lessonsData[i][4] ); //year
    }

    //var blogRowTemplate = "";
    //var blogSectionTemplate = "";

    for( var i = 0; i<count; ++i) {

        //console.log("lesson data row ID : " + lessonsData[i][0]);

        oneResult = blogRowTemplate.replace(story_title_place_holder, lessonsData[i][2]);
        oneResult = oneResult.replace(story_body_place_holder, lessonsData[i][3]);

        //finalPage += oneResult;
        if( lessonsData[i][4] == 2019){

            if( lessonsData[i][5] == 1 ){

                //new blog item is put at beginning of the string, so the new blog item will be shown at top in UI.
                finalPage2019A = oneResult + finalPage2019A;
            }else if( lessonsData[i][5] == 2 ){
                finalPage2019B = oneResult + finalPage2019B;
            }else if( lessonsData[i][5] == 3){
                finalPage2019March = oneResult + finalPage2019March;
            }else if( lessonsData[i][5] == 4){
                finalPage2019April = oneResult + finalPage2019April;
            }else if( lessonsData[i][5] == 5){
                //keep the order of plus. So value item will be shown on top of page.
                finalPage2019May = finalPage2019May + oneResult;
            }else if( lessonsData[i][5] == 6){
                //keep the order of plus. So value item will be shown on top of page.
                finalPage2019June = finalPage2019June + oneResult;
            }else if( lessonsData[i][5] == 7){
                //keep the order of plus. So value item will be shown on top of page.
                finalPage2019July = finalPage2019July + oneResult;
            }else if (lessonsData[i][5] == 8) {
                //keep the order of plus. So value item will be shown on top of page.
                finalPage2019Augest = finalPage2019Augest + oneResult;
            }else if (lessonsData[i][5] == 9) {
                //keep the order of plus. So value item will be shown on top of page.
                finalPage2019September = finalPage2019September + oneResult;
            }else if (lessonsData[i][5] == 10) {
                //keep the order of plus. So value item will be shown on top of page.
                finalPage2019October = finalPage2019October + oneResult;
            }else if (lessonsData[i][5] == 11) {
                //keep the order of plus. So value item will be shown on top of page.
                finalPage2019November = finalPage2019November + oneResult;
            }

        }else if( lessonsData[i][4] == 2018){

            if( lessonsData[i][5] < 7 ){
                //new blog item is put at beginning of the string, so the new blog item will be shown at top in UI.
                finalPage2018A = oneResult + finalPage2018A;
            }else{

                //If item is Oct/Nov/Dec, the item is added at beginning and will be showed on top of blog page.
                if( lessonsData[i][5] > 9 ) {
                    finalPage2018B = oneResult + finalPage2018B;
                }
                else{
                    //If item is Jul/Jun/Aug/Sep, the item is added at end and will be showed on bottom of blog page.
                    finalPage2018B = finalPage2018B + oneResult;
                }
            }

        }else if( lessonsData[i][4] == 2017){

            if( lessonsData[i][5] < 7 ){
                finalPage2017A = oneResult + finalPage2017A;
            }else{
                finalPage2017B = oneResult + finalPage2017B;
            }
        }
        else if(lessonsData[i][4] == 2016){
            finalPage2016 = oneResult + finalPage2016;
        }
    }

    //add two more empty lines to create a bottom margin.
    finalPage2019November = finalPage2019November + "<br/><br/>"
    finalPage2019October = finalPage2019October + "<br/><br/>"
    finalPage2019September = finalPage2019September + "<br/><br/>"
    finalPage2019Augest = finalPage2019Augest + "<br/><br/>"
    finalPage2019July = finalPage2019July + "<br/><br/>"
    finalPage2019June = finalPage2019June + "<br/><br/>"
    finalPage2019May = finalPage2019May + "<br/><br/>"
    finalPage2019April = finalPage2019April + "<br/><br/>"
    finalPage2019March = finalPage2019March + "<br/><br/>"
    finalPage2019B = finalPage2019B + "<br/><br/>"
    finalPage2019A = finalPage2019A + "<br/><br/>"

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"January 2019"); //weather
    finalPage2019A = tempVar.replace(story_section_place_holder,finalPage2019A);

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"February 2019");
    finalPage2019B = tempVar.replace(story_section_place_holder,finalPage2019B);

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"March 2019");
    finalPage2019March = tempVar.replace(story_section_place_holder,finalPage2019March);

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"April 2019");
    finalPage2019April = tempVar.replace(story_section_place_holder,finalPage2019April);

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"May 2019");
    finalPage2019May = tempVar.replace(story_section_place_holder,finalPage2019May);

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"June 2019");
    finalPage2019June = tempVar.replace(story_section_place_holder,finalPage2019June);

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"July 2019");
    finalPage2019July = tempVar.replace(story_section_place_holder,finalPage2019July);

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"August 2019");
    finalPage2019Augest = tempVar.replace(story_section_place_holder,finalPage2019Augest);

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"September 2019");
    finalPage2019September = tempVar.replace(story_section_place_holder,finalPage2019September);

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"October 2019");
    finalPage2019October = tempVar.replace(story_section_place_holder,finalPage2019October);

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"November 2019");
    finalPage2019November = tempVar.replace(story_section_place_holder,finalPage2019November);

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"First Half of 2018");
    finalPage2018A = tempVar.replace(story_section_place_holder,finalPage2018A);

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"Latter Half of 2018");
    finalPage2018B = tempVar.replace(story_section_place_holder,finalPage2018B);

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"First Half of 2017");
    finalPage2017A = tempVar.replace(story_section_place_holder,finalPage2017A);

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"Latter Half of 2017");
    finalPage2017B = tempVar.replace(story_section_place_holder,finalPage2017B);

    tempVar = blogSectionTemplate.replace(blog_section_title_holder,"Year 2016");
    finalPage2016 = tempVar.replace(story_section_place_holder,finalPage2016);

    blogPage2019A = finalPage2019A;
    blogPage2019B = finalPage2019B;
    blogPage2019March = finalPage2019March;
    blogPage2019April = finalPage2019April;
    blogPage2019May = finalPage2019May;
    blogPage2019June = finalPage2019June;
    blogPage2019July = finalPage2019July;
    blogPage2019Aug = finalPage2019Augest;
    blogPage2019Sep = finalPage2019September;
    blogPage2019Oct = finalPage2019October;
    blogPage2019Nov = finalPage2019November;

    blogPage2018A = finalPage2018A;
    blogPage2018B = finalPage2018B;
    blogPage2017A = finalPage2017A;
    blogPage2017B = finalPage2017B;
    blogPage2016 = finalPage2016;
}